def shrink_traced_types(traces: Iterable[CallTrace], max_typed_dict_size: int) -> Tuple[Dict[str, type], Optional[type], Optional[type]]:
    traces_list = list(traces)
    if not traces_list:
        return {}, None, None

    arg_types = {}
    all_keys = set()
    for trace in traces_list:
        all_keys.update(trace.arg_types.keys())

    for key in all_keys:
        types_for_key = [trace.arg_types[key] for trace in traces_list if key in trace.arg_types]
        if types_for_key:
            arg_types[key] = shrink_types(types_for_key, max_typed_dict_size)

    return_types = [trace.return_type for trace in traces_list]
    return_type = shrink_types(return_types, max_typed_dict_size) if return_types else None

    yield_types = [trace.yield_type for trace in traces_list if trace.yield_type is not None]
    yield_type = shrink_types(yield_types, max_typed_dict_size) if yield_types else None

    return arg_types, return_type, yield_type
