def render_signature(sig: inspect.Signature, max_line_len: Optional[int] = None, prefix: str = '') -> str:
    params = [render_parameter(p) for p in sig.parameters.values()]

    return_annotation = ''
    if sig.return_annotation != inspect.Signature.empty:
        return_annotation = ' -> ' + render_annotation(sig.return_annotation)

    if not params:
        return f"({return_annotation})"

    single_line = '(' + ', '.join(params) + ')' + return_annotation

    if max_line_len is None or len(prefix + 'def f' + single_line) <= max_line_len:
        return single_line

    lines = ['(']
    for param in params:
        lines.append(prefix + '    ' + param + ',')
    lines[-1] = lines[-1].rstrip(',')
    lines.append(prefix + ')' + return_annotation)

    return '\n'.join(lines)
